const input = $json.body ?? $json;
const requestedLimit = Number(input.limit ?? 10);
const requestedOffset = Number(input.offset ?? 0);

if (!Number.isInteger(requestedLimit) || requestedLimit < 1 || requestedLimit > 50) {
  throw new Error('El límite debe ser un número entre 1 y 50.');
}
if (!Number.isInteger(requestedOffset) || requestedOffset < 0 || requestedOffset > 10000) {
  throw new Error('La posición debe ser un número entre 0 y 10000.');
}

return [{ json: { limit: requestedLimit, offset: requestedOffset } }];

const response = $json;
const payments = Array.isArray(response.results) ? response.results : [];

const movementLabels = {
  regular_payment: 'Pago',
  pos_payment: 'Pago presencial',
  recurring_payment: 'Pago recurrente',
  settlement: 'Cobro aprobado',
  refund: 'Devolución',
  chargeback: 'Contracargo',
  withdrawal: 'Retiro o transferencia saliente',
  withdrawal_cancel: 'Transferencia cancelada',
  payout: 'Retiro de efectivo',
  money_transfer: 'Solicitud de dinero',
  account_fund: 'Ingreso de fondos',
  partition_transfer: 'Transferencia entre fondos',
};
const paymentTypeLabels = {
  credit_card: 'Tarjeta de crédito',
  debit_card: 'Tarjeta de débito',
  prepaid_card: 'Tarjeta prepaga',
  account_money: 'Dinero en cuenta',
  ticket: 'Efectivo o cupón',
  bank_transfer: 'Transferencia bancaria',
  atm: 'Cajero automático',
  digital_wallet: 'Billetera digital',
};
const directionByType = {
  regular_payment: 'in',
  pos_payment: 'in',
  recurring_payment: 'in',
  settlement: 'in',
  refund: 'out',
  chargeback: 'out',
  withdrawal: 'out',
  withdrawal_cancel: 'in',
  payout: 'out',
  money_transfer: 'in',
  account_fund: 'in',
};

function normalize(raw, labels, fallback) {
  const value = typeof raw === 'string' ? raw.trim() : '';
  return labels[value.toLowerCase()] ?? (value ? fallback + ' (' + value + ')' : 'Sin dato');
}

function cleanName(value) {
  return typeof value === 'string' ? value.trim() : '';
}

function normalizeDirection(value) {
  const direction = typeof value === 'string' ? value.trim().toLowerCase() : '';
  if (['in', 'incoming', 'inbound', 'credit', 'credited'].includes(direction)) return 'in';
  if (['out', 'outgoing', 'outbound', 'debit', 'debited'].includes(direction)) return 'out';
  return null;
}

const safeResults = payments.map((payment) => {
  const operationType = typeof (payment.operation_type ?? payment.OPERATION_TYPE) === 'string'
    ? (payment.operation_type ?? payment.OPERATION_TYPE).trim()
    : '';
  const transactionType = typeof (payment.transaction_type ?? payment.TRANSACTION_TYPE) === 'string'
    ? (payment.transaction_type ?? payment.TRANSACTION_TYPE).trim()
    : '';
  const canonicalType = (transactionType || operationType).toLowerCase();
  const paymentType = typeof (payment.payment_type_id ?? payment.PAYMENT_METHOD_TYPE) === 'string'
    ? (payment.payment_type_id ?? payment.PAYMENT_METHOD_TYPE).trim()
    : '';
  const paymentMethod = typeof (payment.payment_method_id ?? payment.PAYMENT_METHOD) === 'string'
    ? (payment.payment_method_id ?? payment.PAYMENT_METHOD).trim()
    : '';
  const paymentTypeLabel = normalize(paymentType, paymentTypeLabels, 'Otro medio');
  const mappedDirection = directionByType[canonicalType] ?? null;
  const movementDirection = normalizeDirection(
    payment.movement_direction ?? payment.money_direction ?? payment.direction,
  ) ?? mappedDirection;
  const status = typeof (payment.status ?? payment.STATUS) === 'string'
    ? (payment.status ?? payment.STATUS).trim().toLowerCase()
    : '';
  const hasBalanceImpact = status ? status === 'approved' : Boolean(mappedDirection);
  const amountDirection = hasBalanceImpact ? movementDirection : null;
  const payer = payment.payer && typeof payment.payer === 'object' ? payment.payer : {};
  const payerFullName = [cleanName(payer.first_name), cleanName(payer.last_name)]
    .filter(Boolean)
    .join(' ');
  const counterpartName = [
    cleanName(payment.counterpart_name ?? payment.COUNTERPART_NAME),
    cleanName(payment.counterparty_name),
    cleanName(payment.PAYER_NAME),
    cleanName(payer.name),
    payerFullName,
  ].find(Boolean) || '';
  const isTransfer = payment.is_transfer === true
    || canonicalType.includes('transfer')
    || canonicalType === 'account_fund'
    || paymentType.toLowerCase() === 'bank_transfer'
    || paymentMethod.toLowerCase() === 'cvu';
  let counterpartLabel = null;
  if (isTransfer && movementDirection === 'in') {
    counterpartLabel = 'De: ' + (counterpartName || 'No informado');
  } else if (isTransfer && movementDirection === 'out') {
    counterpartLabel = 'Para: ' + (counterpartName || 'No informado');
  } else if (isTransfer) {
    counterpartLabel = 'No informado';
  }

  return {
    id: payment.id ?? null,
    date_created: payment.date_created ?? payment.transaction_date ?? payment.TRANSACTION_DATE ?? null,
    date_approved: payment.date_approved ?? payment.SETTLEMENT_DATE ?? null,
    status: payment.status ?? payment.STATUS ?? null,
    status_detail: payment.status_detail ?? null,
    transaction_amount: payment.transaction_amount ?? payment.TRANSACTION_AMOUNT ?? null,
    currency_id: payment.currency_id ?? payment.transaction_currency ?? payment.TRANSACTION_CURRENCY ?? null,
    movement_type: normalize(transactionType || operationType, movementLabels, 'Otro movimiento'),
    operation_type_raw: operationType || transactionType || null,
    movement_direction: movementDirection,
    amount_direction: amountDirection,
    counterpart_name: counterpartName || null,
    counterpart_label: counterpartLabel,
    payment_method_normalized: paymentMethod
      ? paymentTypeLabel + ' · ' + paymentMethod
      : paymentTypeLabel,
    payment_type_id_raw: paymentType || null,
    payment_method_id_raw: paymentMethod || null,
  };
});

const total = Number(response.paging?.total ?? response.total);
const responseLimit = Number(response.paging?.limit ?? response.limit);
const responseOffset = Number(response.paging?.offset ?? response.offset);

return [{
  json: {
    ok: true,
    total: Number.isFinite(total) ? total : safeResults.length,
    limit: Number.isFinite(responseLimit) ? responseLimit : safeResults.length,
    offset: Number.isFinite(responseOffset) ? responseOffset : 0,
    shown: safeResults.length,
    results: safeResults,
  },
}];
